using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
internal sealed class SongesArchive {internal string Name;internal SongesState State;}
public sealed class SongesRecordBook {public SongesState official,measured;public string officialName="",measuredName="";}
internal static class SongesHistory {
 static SongesRecordBook Book(string directory){foreach(string name in new[]{"songes-records.json","songes-records.json.previous"})try{string file=Path.Combine(directory,name);if(File.Exists(file)&&new FileInfo(file).Length<=2*1024*1024){var book=Store.Json.Deserialize<SongesRecordBook>(File.ReadAllText(file));if(book==null||book.officialName.Length>100||book.measuredName.Length>100)continue;if(book.official!=null)new SongesRun(book.official);if(book.measured!=null)new SongesRun(book.measured);return book;}}catch{}return new SongesRecordBook();}
 internal static void Record(string directory,SongesState state,string name){if(!Won(state))return;var book=Book(directory);bool changed=false;if(state.officialMs>=0&&(book.official==null||state.officialMs<book.official.officialMs)){book.official=state;book.officialName=name;changed=true;}if(state.totalMs>0&&(book.measured==null||state.totalMs<book.measured.totalMs)){book.measured=state;book.measuredName=name;changed=true;}if(!changed)return;Directory.CreateDirectory(directory);string file=Path.Combine(directory,"songes-records.json"),temp=file+".tmp";File.WriteAllText(temp,Store.Json.Serialize(book),new System.Text.UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,file+".previous");else File.Move(temp,file);}
 internal static List<SongesArchive> Read(string directory){var result=new List<SongesArchive>();if(!Directory.Exists(directory))return result;foreach(var file in Directory.EnumerateFiles(directory,"songes-run.json.*.json").OrderByDescending(f=>f).Take(200)){try{if(new FileInfo(file).Length>1024*1024)continue;var state=Store.Json.Deserialize<SongesState>(File.ReadAllText(file));new SongesRun(state);if(state!=null&&state.finished)result.Add(new SongesArchive{Name=File.GetLastWriteTime(file).ToString("dd/MM HH:mm"),State=state});}catch{}}foreach(var archive in result)try{Record(directory,archive.State,archive.Name);}catch{}var saved=Book(directory);if(saved.official!=null)result.Add(new SongesArchive{Name=saved.officialName,State=saved.official});if(saved.measured!=null)result.Add(new SongesArchive{Name=saved.measuredName,State=saved.measured});return result;}
 static bool Won(SongesState s){return s.finished&&(s.outcome=="victoire"||s.fights.Any(f=>f.floor==26&&f.result=="victoire"));}
 static string Delta(long value){return (value>=0?"+":"−")+SongesRun.Duration(Math.Abs(value));}
 internal static string Describe(SongesState current,List<SongesArchive> records){var eligible=records.Where(r=>Won(r.State)).ToList();var official=eligible.Where(r=>r.State.officialMs>=0).OrderBy(r=>r.State.officialMs).FirstOrDefault();var measured=eligible.Where(r=>r.State.totalMs>0).OrderBy(r=>r.State.totalMs).FirstOrDefault();var lines=new List<string>{official==null?"Record officiel : aucun bilan victorieux archivé.":"Record officiel : "+SongesRun.Duration(official.State.officialMs)+" · "+official.Name,measured==null?"Record mesuré : aucune run victorieuse archivée.":"Record mesuré : "+SongesRun.Duration(measured.State.totalMs)+" · "+measured.Name};if(Won(current)&&current.officialMs>=0){if(official==null)lines.Add("Premier temps officiel victorieux : "+SongesRun.Duration(current.officialMs));else{lines.Add("Écart officiel : "+Delta(current.officialMs-official.State.officialMs));if(current.officialMs<official.State.officialMs)lines.Add("Nouveau record officiel pour la run actuelle.");}}if(measured==null)return String.Join("\n",lines);var reference=measured.State.rooms.Where(r=>r.floor>0).GroupBy(r=>r.floor).ToDictionary(g=>g.Key,g=>g.Sum(r=>r.milliseconds));var rooms=current.rooms.Where(r=>r.floor>0).GroupBy(r=>r.floor).ToList();if(rooms.Count>0)lines.Add("\nSalles terminées · comparaison à la meilleure run mesurée");foreach(var room in rooms){long expected;long actual=room.Sum(r=>r.milliseconds);lines.Add("Salle "+room.Key+" · "+SongesRun.Duration(actual)+(reference.TryGetValue(room.Key,out expected)?" · "+Delta(actual-expected):" · sans référence"));}return String.Join("\n",lines);}
 internal static void Test(string folder){var reference=new SongesState{finished=true,outcome="victoire",totalMs=100000,officialMs=99000,rooms=new List<SongesRoom>{new SongesRoom{floor=1,milliseconds=20000}}};var current=new SongesState{finished=true,outcome="victoire",totalMs=110000,officialMs=108000,rooms=new List<SongesRoom>{new SongesRoom{floor=1,milliseconds=23000}}};string text=Describe(current,new List<SongesArchive>{new SongesArchive{Name="Test",State=reference},new SongesArchive{Name="Défaite",State=new SongesState{finished=true,outcome="défaite",totalMs=1,officialMs=1}}});if(!text.Contains("00:01:39")||!text.Contains("+00:00:03")||!text.Contains("+00:00:09"))throw new Exception("Records Songes ou comparaison des salles invalides");string directory=Path.Combine(folder,"songes-history");Directory.CreateDirectory(directory);File.WriteAllText(Path.Combine(directory,"songes-run.json.test.json"),Store.Json.Serialize(reference));File.WriteAllText(Path.Combine(directory,"songes-run.json.bad.json"),"invalide");if(!Read(directory).Any(r=>r.State.officialMs==99000))throw new Exception("Archive valide absente");Record(directory,reference,"Record test");var slower=new SongesState{finished=true,outcome="victoire",totalMs=200000,officialMs=199000};for(int i=0;i<201;i++)File.WriteAllText(Path.Combine(directory,"songes-run.json.zzz"+i.ToString("000")+".json"),Store.Json.Serialize(slower));if(!Describe(current,Read(directory)).Contains("00:01:39"))throw new Exception("Record perdu après 200 archives");}
}
